let mutationRafHandle: number | null = null;
mutationObserver = new MutationObserver((mutations) => {
  for (const m of mutations) for (const n of m.addedNodes) pendingAddedNodes.push(n);
  if (mutationRafHandle === null) {
    mutationRafHandle = requestAnimationFrame(processPendingAddedNodes);
  }
  // keep setTimeout fallback for residual/background tab
  if (mutationTimer) clearTimeout(mutationTimer);
  mutationTimer = setTimeout(() => {
    if (mutationRafHandle !== null) { cancelAnimationFrame(mutationRafHandle); mutationRafHandle = null; }
    processPendingAddedNodes();
  }, MUTATION_DEBOUNCE_MS);
});

