cases.good:
function observeBlock(block) {
  viewport.observe(block.element, {
    onEnter: () => scheduler.schedule(() => bindVisibleBlock(block), PRIORITY_VIEWPORT),
  });
  tryBindVisible(block); // sync bind if already in viewport
}
function tryBindVisible(block) {
  const rect = block.element.getBoundingClientRect();
  if (rect.height > 0 && rect.bottom >= -margin && rect.top <= window.innerHeight + margin) {
    visibleElements.add(block.element);
    bindVisibleBlock(block);
  }
}

